import Foundation

let filePath = "<tmp>"

guard let content = try? String(contentsOfFile: filePath, encoding: .utf8) else {
    fatalError("Could not read file")
}

let lines = content.components(separatedBy: "\n").filter { !$0.trimmingCharacters(in: .whitespaces).isEmpty }

let dataLines = Array(lines.dropFirst())

struct Employee {
    let name: String
    let department: String
    let salary: Double
}

var employees: [Employee] = []

for line in dataLines {
    let fields = line.components(separatedBy: ",")
    guard fields.count >= 6 else { continue }
    let name = fields[1].trimmingCharacters(in: .whitespaces)
    let department = fields[2].trimmingCharacters(in: .whitespaces)
    let salaryStr = fields[3].trimmingCharacters(in: .whitespaces).replacingOccurrences(of: ",", with: "")
    let salary = Double(salaryStr) ?? 0
    let emp = Employee(name: name, department: department, salary: salary)
    employees.append(emp)
}

func formatWithCommas(_ value: Int) -> String {
    let formatter = NumberFormatter()
    formatter.numberStyle = .decimal
    formatter.groupingSeparator = ","
    formatter.groupingSize = 3
    formatter.maximumFractionDigits = 0
    return formatter.string(from: NSNumber(value: value)) ?? "\(value)"
}

func formatWithCommas(_ value: Double, decimals: Int) -> String {
    let formatter = NumberFormatter()
    formatter.numberStyle = .decimal
    formatter.groupingSeparator = ","
    formatter.groupingSize = 3
    formatter.minimumFractionDigits = decimals
    formatter.maximumFractionDigits = decimals
    return formatter.string(from: NSNumber(value: value)) ?? "\(value)"
}

var deptSalaries: [String: [Double]] = [:]
for emp in employees {
    deptSalaries[emp.department, default: []].append(emp.salary)
}

