import Foundation

let filePath = "<tmp>"

guard let content = try? String(contentsOfFile: filePath, encoding: .utf8) else {
    FileHandle.standardError.write("Error reading file\n".data(using: .utf8)!)
    exit(1)
}

let lines = content.components(separatedBy: "\n").filter { !$0.isEmpty }

var levelCounts: [String: Int] = [:]
var componentErrorCounts: [String: Int] = [:]
var errorMessages: Set<String> = []
var hourCounts: [Int: Int] = [:]

for line in lines {
    guard line.hasPrefix("[") else { continue }
    guard let closeBracket = line.firstIndex(of: "]") else { continue }

    let rest = String(line[line.index(after: closeBracket)...]).trimmingCharacters(in: .whitespaces)

    guard let parenIdx = rest.range(of: " (") else { continue }
    let level = String(rest[rest.startIndex..<parenIdx.lowerBound])

    let afterParenSearch = rest[parenIdx.upperBound...]
    guard let closeParenIdx = afterParenSearch.firstIndex(of: ")") else { continue }
    let component = String(afterParenSearch[afterParenSearch.startIndex..<closeParenIdx])

    let afterCloseParen = afterParenSearch[afterParenSearch.index(after: closeParenIdx)...]
    let msgTrimmed = afterCloseParen.trimmingCharacters(in: .whitespaces)
    guard msgTrimmed.hasPrefix("- ") else { continue }
    let message = String(msgTrimmed.dropFirst(2))

    // Extract hour from timestamp: [YYYY-MM-DD HH:MM:SS]
    let timestamp = String(line[line.index(after: line.startIndex)..<closeBracket])
    if timestamp.count >= 13 {
        let idx11 = timestamp.index(timestamp.startIndex, offsetBy: 11)
        let idx13 = timestamp.index(timestamp.startIndex, offsetBy: 13)
        let hourStr = String(timestamp[idx11..<idx13])
        if let hour = Int(hourStr) {
            hourCounts[hour, default: 0] += 1
        }
    }

    levelCounts[level, default: 0] += 1

    if level == "ERROR" {
        componentErrorCounts[component, default: 0] += 1
        errorMessages.insert(message)
    }
}

print("=== Log Analysis ===")
print("")

print("Entries by Level:")
for level in levelCounts.keys.sorted() {
