var componentErrorCounts: [String: Int] = [:]
var errorMessages: Set<String> = []
var hourCounts: [Int: Int] = [:]

for line in lines {
    guard line.hasPrefix("[") else { continue }
    guard let closeBracket = line.firstIndex(of: "]") else { continue }

    let rest = String(line[line.index(after: closeBracket)...]).trimmingCharacters(in: .whitespaces)

    guard let parenIdx = rest.range(of: " (") else { continue }
    let level = String(rest[rest.startIndex..<parenIdx.lowerBound])

    let afterParenSearch = rest[parenIdx.upperBound...]
    guard let closeParenIdx = afterParenSearch.firstIndex(of: ")") else { continue }
    let component = String(afterParenSearch[afterParenSearch.startIndex..<closeParenIdx])

    let afterCloseParen = afterParenSearch[afterParenSearch.index(after: closeParenIdx)...]
    let msgTrimmed = afterCloseParen.trimmingCharacters(in: .whitespaces)
    guard msgTrimmed.hasPrefix("- ") else { continue }
