use std::fs;
use std::collections::BTreeMap;

fn format_comma(n: u64) -> String {
    let s = n.to_string();
    let bytes = s.as_bytes();
    let len = bytes.len();
    let mut result = String::new();
    for (i, b) in bytes.iter().enumerate() {
        result.push(*b as char);
        let remaining = len - i - 1;
        if remaining > 0 && remaining % 3 == 0 {
            result.push(',');
        }
    }
    result
}

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read file");

    let mut lines = content.lines();
    let _header = lines.next();

    let mut dept_salaries: BTreeMap<String, Vec<f64>> = BTreeMap::new();
    let mut dept_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut highest_paid_name = String::new();
    let mut highest_paid_salary: f64 = f64::MIN;
    let mut total_budget: f64 = 0.0;

    for line in lines {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let fields: Vec<&str> = line.split(',').map(|f| f.trim()).collect();
        if fields.len() < 4 {
            continue;
        }
        let name = fields[1].to_string();
        let department = fields[2].to_string();
        let salary: f64 = fields[3].parse().unwrap_or(0.0);

        dept_salaries.entry(department.clone()).or_insert_with(Vec::new).push(salary);
        *dept_counts.entry(department.clone()).or_insert(0) += 1;

        if salary > highest_paid_salary {
            highest_paid_salary = salary;
            highest_paid_name = name;
        }

        total_budget += salary;
    }

    println!("=== Salary Report ===");
    println!();
    println!("Average Salary by Department:");
    for (dept, salaries) in &dept_salaries {
        let avg = salaries.iter().sum::<f64>() / salaries.len() as f64;
        let cents = (avg * 100.0).round() as i64;
        let int_part = cents / 100;
        let dec_part = cents % 100;
        let int_str = format_comma(int_part as u64);
        println!("  {}: ${}.{:02}", dept, int_str, dec_part);
    }
    println!();
    println!(
        "Highest Paid: {} (${})",
        highest_paid_name,
        format_comma(highest_paid_salary.round() as u64)
    );
    println!();
    println!("Departments with >2 employees:");
    for (dept, count) in &dept_counts {
        if *count > 2 {
            println!("  {} ({} employees)", dept, count);
        }
    }
    println!();
    println!(
        "Total Budget: ${}",
        format_comma(total_budget.round() as u64)
    );
}

