    for node in sorted(nodes):
        d = dist[node]
        if d == float('inf'):
            print(f"A -> {node}: unreachable")
        elif isinstance(d, float) and d == int(d):
            print(f"A -> {node}: {int(d)}")
        else:
            print(f"A -> {node}: {d}")

