import java.io.*;
import java.net.*;
import java.util.*;

public class Main {

    static int pos;
    static String json;

    public static void main(String[] args) throws Exception {
        URL url = new URL("http://127.0.0.1:18923/api/products");
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("GET");
        conn.setConnectTimeout(10000);
        conn.setReadTimeout(10000);

        BufferedReader reader = new BufferedReader(new InputStreamReader(conn.getInputStream()));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            sb.append(line);
        }
        reader.close();
        conn.disconnect();

        json = sb.toString();
        pos = 0;
        Object root = parseValue();

        @SuppressWarnings("unchecked")
        List<Map<String, Object>> products = (List<Map<String, Object>>) root;

        List<Map<String, Object>> filtered = new ArrayList<>();
        for (Map<String, Object> p : products) {
            double price = ((Number) p.get("price")).doubleValue();
            if (price > 50.00) {
                filtered.add(p);
            }
        }

        filtered.sort(Comparator.comparing(p -> (String) p.get("name")));

        System.out.println("=== Filtered Products (price > $50.00) ===");
        System.out.println();

        double total = 0.0;
        for (Map<String, Object> p : filtered) {
            String name = (String) p.get("name");
            double price = ((Number) p.get("price")).doubleValue();
            total += price;
            System.out.printf("%s: $%.2f%n", name, price);
        }

        System.out.println();
        System.out.printf("Count: %d%n", filtered.size());
        System.out.printf("Total: $%.2f%n", total);
    }

    static void skipWhitespace() {
        while (pos < json.length() && Character.isWhitespace(json.charAt(pos))) pos++;
    }

    static Object parseValue() {
        skipWhitespace();
        char c = json.charAt(pos);
        if (c == '[') return parseArray();
        if (c == '{') return parseObject();
        if (c == '"') return parseString();
        if (c == 't' || c == 'f') return parseBoolean();
