import * as fs from 'fs';

interface Edge {
  from: string;
  to: string;
  weight: number;
}

interface Graph {
  nodes: string[];
  edges: Edge[];
}

function main(): void {
  const filePath = '<tmp>';
  const data: string = fs.readFileSync(filePath, 'utf-8');
  const graph: Graph = JSON.parse(data);

  // Build adjacency list (undirected)
  const adj: Map<string, Map<string, number>> = new Map();
  for (const node of graph.nodes) {
    adj.set(node, new Map());
  }
  for (const edge of graph.edges) {
    if (!adj.has(edge.from)) adj.set(edge.from, new Map());
    if (!adj.has(edge.to)) adj.set(edge.to, new Map());
    const existing1: number | undefined = adj.get(edge.from)!.get(edge.to);
    if (existing1 === undefined || edge.weight < existing1) {
      adj.get(edge.from)!.set(edge.to, edge.weight);
    }
    const existing2: number | undefined = adj.get(edge.to)!.get(edge.from);
    if (existing2 === undefined || edge.weight < existing2) {
      adj.get(edge.to)!.set(edge.from, edge.weight);
    }
  }

  // Dijkstra's algorithm
  const source: string = 'A';
  const dist: Map<string, number> = new Map();
  const visited: Set<string> = new Set();

  for (const node of graph.nodes) {
    dist.set(node, Infinity);
  }
  dist.set(source, 0);

  const allNodes: string[] = [...graph.nodes];

  for (let i = 0; i < allNodes.length; i++) {
    let minNode: string | null = null;
    let minDist: number = Infinity;
    for (const node of allNodes) {
      if (!visited.has(node) && dist.get(node)! < minDist) {
        minDist = dist.get(node)!;
        minNode = node;
      }
    }

    if (minNode === null || minDist === Infinity) break;

    visited.add(minNode);

    const neighbors: Map<string, number> = adj.get(minNode)!;
    for (const [neighbor, weight] of neighbors) {
      if (!visited.has(neighbor)) {
        const newDist: number = dist.get(minNode)! + weight;
        if (newDist < dist.get(neighbor)!) {
          dist.set(neighbor, newDist);
        }
      }
    }
  }

  // Output
  const sorted: string[] = [...graph.nodes].sort();
  const lines: string[] = [];
  lines.push('=== Shortest Paths from A ===');
  lines.push('');
  for (const node of sorted) {
