        let paren_end = match after_paren_start.find(')') {
            Some(pos) => pos,
            None => continue,
        };
        let component = &after_paren_start[1..paren_end];

        let after_component = &after_paren_start[paren_end + 1..];
        let message = if after_component.starts_with(" - ") {
            &after_component[3..]
        } else {
            after_component
        };

        let hour = if timestamp.len() >= 13 {
            &timestamp[11..13]
        } else {
            continue;
        };

        *level_counts.entry(level.to_string()).or_insert(0) += 1;

        let hour_key = format!("{}:00", hour);
        *hour_counts.entry(hour_key).or_insert(0) += 1;

        if level == "ERROR" {
            *error_component_counts.entry(component.to_string()).or_insert(0) += 1;
            error_messages.push(message.to_string());
