        println!("Component with Most Errors: N/A (0 errors)");
    }
    println!();

    println!("Unique Error Messages:");
    let mut unique_msgs = error_messages.clone();
    unique_msgs.sort();
    unique_msgs.dedup();
    for msg in &unique_msgs {
        println!("  - {}", msg);
    }
    println!();

    let mut hours: Vec<&(String, usize)> = hour_counts.iter().collect();
    hours.sort_by(|a, b| b.1.cmp(a.1).then(a.0.cmp(b.0)));
    if let Some((hour, count)) = hours.first() {
        println!("Busiest Hour: {} ({} entries)", hour, count);
    } else {
        println!("Busiest Hour: N/A (0 entries)");
    }
}

