#define NAME_SIZE 256

typedef struct {
    char name[NAME_SIZE];
    double total_salary;
    int count;
} DeptInfo;

int compare_depts(const void *a, const void *b) {
    const DeptInfo *da = (const DeptInfo *)a;
    const DeptInfo *db = (const DeptInfo *)b;
    return strcmp(da->name, db->name);
}

void format_money(double val, int decimals, char *buf, size_t bufsize) {
    long long ival;
    int dec = 0;
    char dec_str[8] = "";

    if (decimals == 0) {
        ival = (long long)(val + 0.5);
    } else {
        long long cents = (long long)(val * 100.0 + 0.5);
        ival = cents / 100;
        dec = (int)(cents % 100);
        snprintf(dec_str, sizeof(dec_str), ".%02d", dec);
    }

    char int_str[32];
    snprintf(int_str, sizeof(int_str), "%lld", ival);

    int int_len = strlen(int_str);
    int pos = 0;
    buf[pos++] = '$';

    int start = 0;
    if (int_str[0] == '-') {
        buf[pos++] = '-';
        start = 1;
    }

    int digits = int_len - start;
    for (int i = 0; i < digits; i++) {
        buf[pos++] = int_str[start + i];
        int remaining = digits - i - 1;
        if (remaining > 0 && remaining % 3 == 0) {
            buf[pos++] = ',';
        }
    }

    for (int i = 0; dec_str[i]; i++) {
        buf[pos++] = dec_str[i];
    }
    buf[pos] = '\0';
}

int main(void) {
