    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s\n", filename);
        return 1;
    }

    int dept_cap = 64;
    int dept_count = 0;
    DeptInfo *depts = (DeptInfo *)malloc((size_t)dept_cap * sizeof(DeptInfo));
    if (!depts) {
        fclose(fp);
        return 1;
