    char *line = (char *)malloc(MAX_LINE);
    if (!line) {
        free(depts);
        fclose(fp);
        return 1;
    }

    int first_line = 1;

    while (fgets(line, MAX_LINE, fp)) {
        if (first_line) {
            first_line = 0;
            continue;
        }

        line[strcspn(line, "\r\n")] = '\0';
        if (line[0] == '\0') continue;

        char *fields[6];
        int nf = 0;
        char *p = line;
        fields[nf++] = p;
        while (*p) {
            if (*p == ',') {
                *p = '\0';
                if (nf < 6) fields[nf++] = p + 1;
            }
            p++;
        }

        if (nf < 4) continue;

        const char *name = fields[1];
        const char *dept_name = fields[2];
        double salary = atof(fields[3]);

        total_budget += salary;

        if (salary > max_salary) {
            max_salary = salary;
            strncpy(max_name, name, NAME_SIZE - 1);
            max_name[NAME_SIZE - 1] = '\0';
        }

        int found = -1;
        for (int i = 0; i < dept_count; i++) {
            if (strcmp(depts[i].name, dept_name) == 0) {
                found = i;
                break;
            }
        }

        if (found == -1) {
            if (dept_count >= dept_cap) {
                dept_cap *= 2;
                depts = (DeptInfo *)realloc(depts, (size_t)dept_cap * sizeof(DeptInfo));
                if (!depts) {
                    free(line);
                    fclose(fp);
                    return 1;
                }
            }
            found = dept_count++;
            strncpy(depts[found].name, dept_name, NAME_SIZE - 1);
            depts[found].name[NAME_SIZE - 1] = '\0';
            depts[found].total_salary = 0.0;
            depts[found].count = 0;
        }

        depts[found].total_salary += salary;
        depts[found].count++;
    }

    free(line);
    fclose(fp);

    qsort(depts, (size_t)dept_count, sizeof(DeptInfo), compare_depts);

    printf("=== Salary Report ===\n");
    printf("\n");
    printf("Average Salary by Department:\n");

    for (int i = 0; i < dept_count; i++) {
        double avg = depts[i].total_salary / (double)depts[i].count;
        char buf[64];
        format_money(avg, 2, buf, sizeof(buf));
        printf("  %s: %s\n", depts[i].name, buf);
    }

    printf("\n");
    {
        char buf[64];
        format_money(max_salary, 0, buf, sizeof(buf));
        printf("Highest Paid: %s (%s)\n", max_name, buf);
    }

    printf("\n");
    printf("Departments with >2 employees:\n");
    for (int i = 0; i < dept_count; i++) {
        if (depts[i].count > 2) {
            printf("  %s (%d employees)\n", depts[i].name, depts[i].count);
        }
    }

    printf("\n");
    {
        char buf[64];
        format_money(total_budget, 0, buf, sizeof(buf));
        printf("Total Budget: %s\n", buf);
    }

    free(depts);
    return 0;
