static int json_equal(const json_value *a, const json_value *b) {
    if (!a || !b) return a == b;
    if (a->type != b->type) return 0;
    switch (a->type) {
    case JSON_NULL: return 1;
    case JSON_BOOL: return a->bool_val == b->bool_val;
    case JSON_NUMBER:
        if (a->is_int && b->is_int) return a->int_val == b->int_val;
        if (a->is_int != b->is_int) return 0;
        return a->dbl_val == b->dbl_val;
    case JSON_STRING: return strcmp(a->str_val, b->str_val) == 0;
    case JSON_ARRAY:
        if (a->item_count != b->item_count) return 0;
        for (int i = 0; i < a->item_count; i++)
            if (!json_equal(a->items[i], b->items[i])) return 0;
        return 1;
    case JSON_OBJECT:
        if (a->key_count != b->key_count) return 0;
        for (int i = 0; i < a->key_count; i++) {
            int found = 0;
            for (int j = 0; j < b->key_count; j++) {
                if (strcmp(a->keys[i], b->keys[j]) == 0) {
                    if (json_equal(a->values[i], b->values[j])) { found = 1; break; }
                    else return 0;
