static int json_equal(const json_value *a, const json_value *b) {
    if (!a || !b) return a == b;
    if (a->type != b->type) return 0;
    switch (a->type) {
    case JSON_NULL: return 1;
    case JSON_BOOL: return a->bool_val == b->bool_val;
    case JSON_NUMBER:
        if (a->is_int && b->is_int) return a->int_val == b->int_val;
        if (a->is_int != b->is_int) return 0;
        return a->dbl_val == b->dbl_val;
    case JSON_STRING: return strcmp(a->str_val, b->str_val) == 0;
    case JSON_ARRAY:
        if (a->item_count != b->item_count) return 0;
        for (int i = 0; i < a->item_count; i++)
            if (!json_equal(a->items[i], b->items[i])) return 0;
        return 1;
    case JSON_OBJECT:
        if (a->key_count != b->key_count) return 0;
        for (int i = 0; i < a->key_count; i++) {
            int found = 0;
            for (int j = 0; j < b->key_count; j++) {
                if (strcmp(a->keys[i], b->keys[j]) == 0) {
                    if (json_equal(a->values[i], b->values[j])) { found = 1; break; }
                    else return 0;
                }
            }
            if (!found) return 0;
        }
        return 1;
    }
    return 0;
}

static int array_contains(const json_value *arr, const json_value *item) {
    if (arr->type != JSON_ARRAY) return 0;
    for (int i = 0; i < arr->item_count; i++)
        if (json_equal(arr->items[i], item)) return 1;
    return 0;
}

static void array_push(json_value *arr, json_value *item) {
    if (arr->item_count >= arr->item_cap) {
        arr->item_cap = arr->item_cap ? arr->item_cap * 2 : 4;
        arr->items = (json_value **)realloc(arr->items, arr->item_cap * sizeof(json_value *));
        if (!arr->items) { fprintf(stderr, "OOM\n"); exit(1); }
    }
    arr->items[arr->item_count++] = item;
}

static void obj_set(json_value *obj, const char *key, json_value *val) {
    for (int i = 0; i < obj->key_count; i++) {
        if (strcmp(obj->keys[i], key) == 0) {
            json_free(obj->values[i]);
            obj->values[i] = val;
            return;
        }
    }
    if (obj->key_count >= obj->key_cap) {
        obj->key_cap = obj->key_cap ? obj->key_cap * 2 : 4;
        obj->keys = (char **)realloc(obj->keys, obj->key_cap * sizeof(char *));
        obj->values = (json_value **)realloc(obj->values, obj->key_cap * sizeof(json_value *));
        if (!obj->keys || !obj->values) { fprintf(stderr, "OOM\n"); exit(1); }
    }
    obj->keys[obj->key_count] = strdup(key);
    obj->values[obj->key_count] = val;
    obj->key_count++;
}

static json_value *deep_merge(const json_value *a, const json_value *b) {
    if (a->type == JSON_OBJECT && b->type == JSON_OBJECT) {
        json_value *result = json_new(JSON_OBJECT);
        for (int i = 0; i < a->key_count; i++) {
            int found = 0;
            for (int j = 0; j < b->key_count; j++) {
                if (strcmp(a->keys[i], b->keys[j]) == 0) {
                    obj_set(result, a->keys[i], deep_merge(a->values[i], b->values[j]));
                    found = 1;
                    break;
                }
            }
            if (!found) {
                obj_set(result, a->keys[i], json_deep_copy(a->values[i]));
            }
        }
        for (int j = 0; j < b->key_count; j++) {
            int found = 0;
            for (int i = 0; i < a->key_count; i++) {
                if (strcmp(a->keys[i], b->keys[j]) == 0) { found = 1; break; }
            }
            if (!found) {
                obj_set(result, b->keys[j], json_deep_copy(b->values[j]));
            }
        }
        return result;
    }
    if (a->type == JSON_ARRAY && b->type == JSON_ARRAY) {
        json_value *result = json_new(JSON_ARRAY);
        for (int i = 0; i < a->item_count; i++)
            array_push(result, json_deep_copy(a->items[i]));
        for (int i = 0; i < b->item_count; i++) {
            if (!array_contains(result, b->items[i]))
                array_push(result, json_deep_copy(b->items[i]));
        }
        return result;
    }
    return json_deep_copy(b);
}

static void sort_object_keys(json_value *obj) {
    if (obj->type != JSON_OBJECT || obj->key_count <= 1) return;
    for (int i = 0; i < obj->key_count; i++)
        sort_object_keys(obj->values[i]);
    for (int i = 0; i < obj->item_count; i++)
        if (obj->items[i]->type == JSON_OBJECT) sort_object_keys(obj->items[i]);
    /* sort keys */
    for (int i = 1; i < obj->key_count; i++) {
        const char *k = obj->keys[i];
        json_value *v = obj->values[i];
        int j = i - 1;
        while (j >= 0 && strcmp(obj->keys[j], k) > 0) {
            obj->keys[j+1] = obj->keys[j];
            obj->values[j+1] = obj->values[j];
            j--;
        }
        obj->keys[j+1] = k;
        obj->values[j+1] = v;
    }
}

static void sort_array_items(json_value *arr) {
    if (arr->type != JSON_ARRAY) return;
    for (int i = 0; i < arr->item_count; i++) {
        if (arr->items[i]->type == JSON_OBJECT) sort_object_keys(arr->items[i]);
        else if (arr->items[i]->type == JSON_ARRAY) sort_array_items(arr->items[i]);
    }
}

static void sort_json(json_value *v) {
    if (!v) return;
    if (v->type == JSON_OBJECT) sort_object_keys(v);
    else if (v->type == JSON_ARRAY) sort_array_items(v);
}

static void print_string(const char *s, FILE *f) {
    fputc('"', f);
    for (const char *p = s; *p; p++) {
        unsigned char c = (unsigned char)*p;
        switch (c) {
        case '"': fputs("\\\"", f); break;
        case '\\': fputs("\\\\", f); break;
        case '\b': fputs("\\b", f); break;
        case '\f': fputs("\\f", f); break;
        case '\n': fputs("\\n", f); break;
        case '\r': fputs("\\r", f); break;
        case '\t': fputs("\\t", f); break;
        default:
            if (c < 0x20) fprintf(f, "\\u%04x", c);
            else fputc(c, f);
        }
    }
    fputc('"', f);
}

static void print_number(const json_value *v, FILE *f) {
    if (v->is_int) {
        fprintf(f, "%lld", v->int_val);
    } else {
        /* Print without trailing zeros if possible, but always with decimal point */
        char buf[64];
        /* Try to print as integer if it's a whole number */
        if (v->dbl_val == (double)(long long)v->dbl_val && fabs(v->dbl_val) < 1e15) {
            fprintf(f, "%lld.0", (long long)v->dbl_val);
        } else {
            snprintf(buf, sizeof(buf), "%.15g", v->dbl_val);
            /* Ensure it has a decimal point or exponent to distinguish from int */
            int has_dot = 0, has_exp = 0;
            for (int i = 0; buf[i]; i++) {
                if (buf[i] == '.') has_dot = 1;
                if (buf[i] == 'e' || buf[i] == 'E') has_exp = 1;
            }
            if (!has_dot && !has_exp) {
                fprintf(f, "%s.0", buf);
            } else {
                fprintf(f, "%s", buf);
            }
        }
    }
}

static void print_json(const json_value *v, int indent, FILE *f) {
    if (!v) { fprintf(f, "null"); return; }
    switch (v->type) {
    case JSON_NULL:
        fprintf(f, "null");
        break;
    case JSON_BOOL:
        fprintf(f, v->bool_val ? "true" : "false");
        break;
    case JSON_NUMBER:
        print_number(v, f);
        break;
    case JSON_STRING:
        print_string(v->str_val, f);
        break;
    case JSON_ARRAY:
        if (v->item_count == 0) {
            fprintf(f, "[]");
            break;
        }
        fprintf(f, "[\n");
        for (int i = 0; i < v->item_count; i++) {
            for (int s = 0; s < (indent + 1) * 2; s++) fputc(' ', f);
            print_json(v->items[i], indent + 1, f);
            if (i < v->item_count - 1) fputc(',', f);
            fputc('\n', f);
        }
        for (int s = 0; s < indent * 2; s++) fputc(' ', f);
        fprintf(f, "]");
        break;
    case JSON_OBJECT:
        if (v->key_count == 0) {
            fprintf(f, "{}");
            break;
        }
        fprintf(f, "{\n");
        for (int i = 0; i < v->key_count; i++) {
            for (int s = 0; s < (indent + 1) * 2; s++) fputc(' ', f);
            print_string(v->keys[i], f);
            fprintf(f, ": ");
            print_json(v->values[i], indent + 1, f);
            if (i < v->key_count - 1) fputc(',', f);
            fputc('\n', f);
        }
        for (int s = 0; s < indent * 2; s++) fputc(' ', f);
        fprintf(f, "}");
        break;
    }
}

/* JSON Parser */
typedef struct {
    const char *buf;
    int pos;
    int len;
} parser;

static void skip_ws(parser *p) {
    while (p->pos < p->len) {
        char c = p->buf[p->pos];
        if (c == ' ' || c == '\t' || c == '\n' || c == '\r') p->pos++;
        else break;
    }
}

static char hex4(parser *p) {
    if (p->pos + 4 > p->len) return 0;
    char h[5] = {0};
    for (int i = 0; i < 4; i++) h[i] = p->buf[p->pos++];
    return (char)strtol(h, NULL, 16);
}

static void parse_string_raw(parser *p, char **out) {
    /* assumes p->buf[p->pos] == '"' */
    p->pos++; /* skip opening quote */
    int cap = 64;
    char *s = (char *)malloc(cap);
    int n = 0;
    while (p->pos < p->len && p->buf[p->pos] != '"') {
        char c = p->buf[p->pos];
        if (c == '\\') {
            p->pos++;
            if (p->pos >= p->len) break;
            char e = p->buf[p->pos];
            char out_c = 0;
            switch (e) {
            case '"': out_c = '"'; break;
            case '\\': out_c = '\\'; break;
            case '/': out_c = '/'; break;
            case 'b': out_c = '\b'; break;
            case 'f': out_c = '\f'; break;
            case 'n': out_c = '\n'; break;
            case 'r': out_c = '\r'; break;
            case 't': out_c = '\t'; break;
            case 'u':
                p->pos++;
                out_c = hex4(p);
                /* Check for surrogate pair */
                if (out_c >= 0xD800 && out_c <= 0xDBFF && p->pos + 1 < p->len && p->buf[p->pos] == '\\' && p->buf[p->pos+1] == 'u') {
                    p->pos += 2;
                    char lo = hex4(p);
                    if (lo >= 0xDC00 && lo <= 0xDFFF) {
                        int cp = 0x10000 + ((out_c - 0xD800) << 10) + (lo - 0xDC00);
                        /* Encode as UTF-8 */
                        if (n + 4 >= cap) { cap *= 2; s = realloc(s, cap); }
                        if (cp < 0x10000) {
                            s[n++] = 0xE0 | (cp >> 12);
                            s[n++] = 0x80 | ((cp >> 6) & 0x3F);
                            s[n++] = 0x80 | (cp & 0x3F);
                        } else {
                            s[n++] = 0xF0 | (cp >> 18);
                            s[n++] = 0x80 | ((cp >> 12) & 0x3F);
                            s[n++] = 0x80 | ((cp >> 6) & 0x3F);
                            s[n++] = 0x80 | (cp & 0x3F);
                        }
                        continue;
                    }
                }
                /* single char from hex (may not be valid UTF-8 but store as-is) */
                if (n + 1 >= cap) { cap *= 2; s = realloc(s, cap); }
                s[n++] = out_c;
                continue;
            default:
                out_c = e;
                break;
            }
            p->pos++;
            if (n + 1 >= cap) { cap *= 2; s = realloc(s, cap); }
            s[n++] = out_c;
        } else {
            if (n + 1 >= cap) { cap *= 2; s = realloc(s, cap); }
            s[n++] = c;
            p->pos++;
        }
    }
    if (p->pos < p->len) p->pos++; /* skip closing quote */
    if (n + 1 >= cap) { cap = n + 1; s = realloc(s, cap); }
    s[n] = '\0';
    *out = s;
}

static json_value *parse_value(parser *p);

static json_value *parse_object(parser *p) {
    p->pos++; /* skip '{' */
    json_value *obj = json_new(JSON_OBJECT);
    skip_ws(p);
    if (p->pos < p->len && p->buf[p->pos] == '}') {
        p->pos++;
        return obj;
    }
    while (1) {
        skip_ws(p);
        if (p->pos >= p->len) break;
        /* parse key */
        char *key;
        parse_string_raw(p, &key);
        skip_ws(p);
        if (p->pos < p->len && p->buf[p->pos] == ':') p->pos++;
        skip_ws(p);
        json_value *val = parse_value(p);
        obj_set(obj, key, val);
        free(key);
        skip_ws(p);
        if (p->pos < p->len && p->buf[p->pos] == ',') {
            p->pos++;
            skip_ws(p);
        } else if (p->pos < p->len && p->buf[p->pos] == '}') {
            p->pos++;
            break;
        } else {
            break;
        }
    }
    return obj;
}

static json_value *parse_array(parser *p) {
    p->pos++; /* skip '[' */
    json_value *arr = json_new(JSON_ARRAY);
    skip_ws(p);
    if (p->pos < p->len && p->buf[p->pos] == ']') {
        p->pos++;
        return arr;
    }
    while (1) {
        skip_ws(p);
        if (p->pos >= p->len) break;
        json_value *val = parse_value(p);
        array_push(arr, val);
        skip_ws(p);
        if (p->pos < p->len && p->buf[p->pos] == ',') {
            p->pos++;
            skip_ws(p);
        } else if (p->pos < p->len && p->buf[p->pos] == ']') {
            p->pos++;
            break;
        } else {
            break;
        }
    }
    return arr;
}

static json_value *parse_number(parser *p) {
    int start = p->pos;
    int is_int = 1;
    if (p->pos < p->len && p->buf[p->pos] == '-') p->pos++;
    while (p->pos < p->len && isdigit((unsigned char)p->buf[p->pos])) p->pos++;
    if (p->pos < p->len && p->buf[p->pos] == '.') {
        is_int = 0;
        p->pos++;
        while (p->pos < p->len && isdigit((unsigned char)p->buf[p->pos])) p->pos++;
    }
    if (p->pos < p->len && (p->buf[p->pos] == 'e' || p->buf[p->pos] == 'E')) {
        is_int = 0;
        p->pos++;
        if (p->pos < p->len && (p->buf[p->pos] == '+' || p->buf[p->pos] == '-')) p->pos++;
        while (p->pos < p->len && isdigit((unsigned char)p->buf[p->pos])) p->pos++;
    }
    int len = p->pos - start;
    char *numstr = (char *)malloc(len + 1);
    memcpy(numstr, p->buf + start, len);
    numstr[len] = '\0';
    json_value *v = json_new(JSON_NUMBER);
    if (is_int) {
        v->is_int = 1;
        v->int_val = atoll(numstr);
        v->dbl_val = (double)v->int_val;
    } else {
        v->is_int = 0;
        v->dbl_val = atof(numstr);
        v->int_val = (long long)v->dbl_val;
    }
    free(numstr);
    return v;
}

static json_value *parse_value(parser *p) {
    skip_ws(p);
    if (p->pos >= p->len) return json_new(JSON_NULL);
    char c = p->buf[p->pos];
    if (c == '{') return parse_object(p);
    if (c == '[') return parse_array(p);
    if (c == '"') {
        json_value *v = json_new(JSON_STRING);
        parse_string_raw(p, &v->str_val);
        return v;
    }
    if (c == '-' || isdigit((unsigned char)c)) return parse_number(p);
    if (p->pos + 4 <= p->len && strncmp(p->buf + p->pos, "true", 4) == 0) {
        p->pos += 4;
        json_value *v = json_new(JSON_BOOL);
        v->bool_val = 1;
        return v;
    }
    if (p->pos + 5 <= p->len && strncmp(p->buf + p->pos, "false", 5) == 0) {
        p->pos += 5;
        json_value *v = json_new(JSON_BOOL);
        v->bool_val = 0;
        return v;
    }
    if (p->pos + 4 <= p->len && strncmp(p->buf + p->pos, "null", 4) == 0) {
        p->pos += 4;
        return json_new(JSON_NULL);
    }
    /* fallback */
    p->pos++;
    return json_new(JSON_NULL);
}

static char *read_file(const char *path, size_t *out_len) {
    FILE *f = fopen(path, "rb");
    if (!f) {
        fprintf(stderr, "Cannot open %s\n", path);
        exit(1);
    }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = (char *)malloc((size_t)sz + 1);
    if (!buf) { fprintf(stderr, "OOM\n"); exit(1); }
    size_t rd = fread(buf, 1, (size_t)sz, f);
    buf[rd] = '\0';
    *out_len = rd;
    fclose(f);
    return buf;
}

int main(void) {
    const char *path_a = "<tmp>";
    const char *path_b = "<tmp>";

    size_t len_a, len_b;
    char *buf_a = read_file(path_a, &len_a);
    char *buf_b = read_file(path_b, &len_b);

    parser pa = { buf_a, 0, (int)len_a };
    parser pb = { buf_b, 0, (int)len_b };

    json_value *a = parse_value(&pa);
    json_value *b = parse_value(&pb);

    json_value *merged = deep_merge(a, b);

    sort_json(merged);

    print_json(merged, 0, stdout);
    fputc('\n', stdout);

    json_free(a);
    json_free(b);
    json_free(merged);
    free(buf_a);
    free(buf_b);

    return 0;
}
