use std::collections::BTreeMap;
use std::fs;

#[derive(Debug, Clone, PartialEq)]
enum Json {
    Null,
    Bool(bool),
    Number(String),
    String(String),
    Array(Vec<Json>),
    Object(BTreeMap<String, Json>),
}

struct Parser {
    chars: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(s: &str) -> Self {
        Parser { chars: s.chars().collect(), pos: 0 }
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn next(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn skip_whitespace(&mut self) {
        while let Some(c) = self.peek() {
            if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn parse_value(&mut self) -> Result<Json, String> {
        self.skip_whitespace();
        match self.peek() {
            Some('{') => self.parse_object(),
            Some('[') => self.parse_array(),
            Some('"') => self.parse_string().map(Json::String),
            Some('t') => {
                self.expect_str("true")?;
                Ok(Json::Bool(true))
            }
            Some('f') => {
                self.expect_str("false")?;
                Ok(Json::Bool(false))
            }
            Some('n') => {
                self.expect_str("null")?;
                Ok(Json::Null)
            }
            Some(c) if c == '-' || c.is_ascii_digit() => self.parse_number(),
            _ => Err(format!("Unexpected character at position {}", self.pos)),
        }
    }

    fn expect_str(&mut self, s: &str) -> Result<(), String> {
        for c in s.chars() {
            match self.next() {
                Some(x) if x == c => {}
                _ => return Err(format!("Expected '{}'", s)),
            }
        }
        Ok(())
    }

    fn parse_number(&mut self) -> Result<Json, String> {
        let start = self.pos;
        if self.peek() == Some('-') {
            self.pos += 1;
        }
        if self.peek() == Some('0') {
            self.pos += 1;
        } else if let Some(c) = self.peek() {
            if c.is_ascii_digit() {
                while let Some(c) = self.peek() {
                    if c.is_ascii_digit() {
                        self.pos += 1;
                    } else {
                        break;
                    }
                }
            } else {
                return Err("Invalid number".into());
            }
        } else {
            return Err("Invalid number".into());
        }
        if self.peek() == Some('.') {
            self.pos += 1;
            let mut has_digit = false;
            while let Some(c) = self.peek() {
                if c.is_ascii_digit() {
                    self.pos += 1;
                    has_digit = true;
                } else {
                    break;
                }
            }
            if !has_digit {
                return Err("Invalid number: expected digit after '.'".into());
            }
        }
        if let Some(c) = self.peek() {
            if c == 'e' || c == 'E' {
                self.pos += 1;
                if let Some(c) = self.peek() {
                    if c == '+' || c == '-' {
                        self.pos += 1;
                    }
                }
                let mut has_digit = false;
                while let Some(c) = self.peek() {
                    if c.is_ascii_digit() {
                        self.pos += 1;
                        has_digit = true;
                    } else {
                        break;
                    }
                }
                if !has_digit {
                    return Err("Invalid number: expected digit in exponent".into());
                }
            }
        }
        let s: String = self.chars[start..self.pos].iter().cloned().collect();
        Ok(Json::Number(s))
    }

    fn parse_string(&mut self) -> Result<String, String> {
        self.next();
        let mut result = String::new();
        loop {
            match self.next() {
                None => return Err("Unterminated string".into()),
                Some('"') => break,
                Some('\\') => {
                    match self.next() {
                        Some('"') => result.push('"'),
                        Some('\\') => result.push('\\'),
                        Some('/') => result.push('/'),
                        Some('b') => result.push('\u{0008}'),
                        Some('f') => result.push('\u{000C}'),
                        Some('n') => result.push('\n'),
                        Some('r') => result.push('\r'),
                        Some('t') => result.push('\t'),
                        Some('u') => {
                            let mut code = 0u32;
                            for _ in 0..4 {
                                let c = self.next().ok_or("Invalid unicode escape")?;
                                let d = hex_digit(c)?;
                                code = code * 16 + d;
                            }
                            if (0xD800..=0xDBFF).contains(&code) {
                                if self.peek() == Some('\\') {
                                    self.pos += 1;
                                    if self.peek() == Some('u') {
                                        self.pos += 1;
                                        let mut low = 0u32;
                                        for _ in 0..4 {
                                            let c = self.next().ok_or("Invalid unicode escape")?;
                                            let d = hex_digit(c)?;
                                            low = low * 16 + d;
                                        }
                                        if (0xDC00..=0xDFFF).contains(&low) {
                                            let cp = 0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00);
                                            result.push(char::from_u32(cp).ok_or("Invalid code point")?);
                                        } else {
                                            return Err("Invalid low surrogate".into());
                                        }
                                    } else {
                                        return Err("Expected \\u for surrogate pair".into());
                                    }
                                } else {
                                    return Err("Expected \\u for surrogate pair".into());
                                }
                            } else {
                                result.push(char::from_u32(code).ok_or("Invalid code point")?);
                            }
                        }
                        _ => return Err("Invalid escape sequence".into()),
                    }
                }
                Some(c) => result.push(c),
            }
        }
        Ok(result)
    }

    fn parse_object(&mut self) -> Result<Json, String> {
        self.next();
        let mut map = BTreeMap::new();
        self.skip_whitespace();
        if self.peek() == Some('}') {
            self.next();
            return Ok(Json::Object(map));
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string()?;
            self.skip_whitespace();
            if self.next() != Some(':') {
                return Err("Expected ':'".into());
            }
            self.skip_whitespace();
            let val = self.parse_value()?;
            map.insert(key, val);
            self.skip_whitespace();
            match self.next() {
                Some(',') => continue,
                Some('}') => break,
                _ => return Err("Expected ',' or '}'".into()),
            }
        }
        Ok(Json::Object(map))
    }

    fn parse_array(&mut self) -> Result<Json, String> {
        self.next();
        let mut arr = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(']') {
            self.next();
            return Ok(Json::Array(arr));
        }
        loop {
            self.skip_whitespace();
            let val = self.parse_value()?;
            arr.push(val);
            self.skip_whitespace();
            match self.next() {
                Some(',') => continue,
                Some(']') => break,
                _ => return Err("Expected ',' or ']'".into()),
            }
        }
        Ok(Json::Array(arr))
    }
}

fn hex_digit(c: char) -> Result<u32, String> {
    match c {
        '0'..='9' => Ok((c as u32) - ('0' as u32)),
        'a'..='f' => Ok((c as u32) - ('a' as u32) + 10),
        'A'..='F' => Ok((c as u32) - ('A' as u32) + 10),
        _ => Err(format!("Invalid hex digit: {}", c)),
    }
}

fn deep_merge(a: Json, b: Json) -> Json {
    match (&a, &b) {
        (Json::Object(_), Json::Object(_)) => {
            let mut result = BTreeMap::new();
            if let Json::Object(ref a_map) = a {
                for (k, v) in a_map {
                    result.insert(k.clone(), v.clone());
                }
            }
            if let Json::Object(ref b_map) = b {
                for (k, v) in b_map {
                    if let Some(a_val) = result.get(k) {
                        result.insert(k.clone(), deep_merge(a_val.clone(), v.clone()));
                    } else {
                        result.insert(k.clone(), v.clone());
                    }
                }
            }
            Json::Object(result)
        }
        (Json::Array(_), Json::Array(_)) => {
            let a_arr = if let Json::Array(ref a) = a { a.clone() } else { unreachable!() };
            let b_arr = if let Json::Array(ref b) = b { b.clone() } else { unreachable!() };
            let mut result = a_arr;
            for item in &b_arr {
                if !result.contains(item) {
                    result.push(item.clone());
                }
            }
            Json::Array(result)
        }
        _ => b,
    }
}

fn escape_string(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            '\u{0008}' => result.push_str("\\b"),
            '\u{000C}' => result.push_str("\\f"),
            c if (c as u32) < 0x20 => {
                result.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => result.push(c),
        }
    }
    result
}

fn serialize_json(val: &Json, indent: usize) -> String {
    let pad = "  ".repeat(indent);
    let pad_inner = "  ".repeat(indent + 1);

    match val {
        Json::Null => "null".to_string(),
        Json::Bool(b) => b.to_string(),
        Json::Number(n) => n.clone(),
        Json::String(s) => format!("\"{}\"", escape_string(s)),
        Json::Array(arr) => {
            if arr.is_empty() {
                return "[]".to_string();
            }
            let mut parts = Vec::new();
            for item in arr {
                parts.push(format!("{}{}", pad_inner, serialize_json(item, indent + 1)));
            }
            format!("[\n{}\n{}]", parts.join(",\n"), pad)
        }
        Json::Object(map) => {
            if map.is_empty() {
                return "{}".to_string();
            }
            let mut parts = Vec::new();
            for (k, v) in map {
                let key_str = format!("\"{}\"", escape_string(k));
                parts.push(format!("{}{}: {}", pad_inner, key_str, serialize_json(v, indent + 1)));
            }
            format!("{{\n{}\n{}}}", parts.join(",\n"), pad)
        }
    }
}

fn main() {
    let path_a = "<tmp>";
    let path_b = "<tmp>";

    let content_a = fs::read_to_string(path_a).expect("Failed to read config_a.json");
    let content_b = fs::read_to_string(path_b).expect("Failed to read config_b.json");

    let mut parser_a = Parser::new(&content_a);
    let json_a = parser_a.parse_value().expect("Failed to parse config_a.json");

    let mut parser_b = Parser::new(&content_b);
    let json_b = parser_b.parse_value().expect("Failed to parse config_b.json");

    let merged = deep_merge(json_a, json_b);

    let output = serialize_json(&merged, 0);
    println!("{}", output);
}

