fn main() {
    let root = Path::new("<tmp>");

    let mut files: Vec<(String, u64, u64)> = Vec::new();
    walk_dir(root, root, &mut files);

    let mut groups: BTreeMap<String, Vec<(String, u64, u64)>> = BTreeMap::new();
    for (rel_path, lines, chars) in &files {
        let p = Path::new(rel_path);
        let ext = p.extension()
            .map(|e| format!(".{}", e.to_string_lossy()))
            .unwrap_or_default();
        groups.entry(ext).or_default().push((rel_path.clone(), *lines, *chars));
    }

    for v in groups.values_mut() {
        v.sort_by(|a, b| a.0.cmp(&b.0));
    }

    println!("=== File Tree Analysis ===");
    println!();

    let mut total_files: u64 = 0;
    let mut total_lines: u64 = 0;
    let mut total_chars: u64 = 0;

    for (ext, file_list) in &groups {
        total_files += file_list.len() as u64;
        let ext_lines: u64 = file_list.iter().map(|f| f.1).sum();
        let ext_chars: u64 = file_list.iter().map(|f| f.2).sum();
        total_lines += ext_lines;
        total_chars += ext_chars;

        println!("Extension: {}", ext);
        println!("  Files: {}", file_list.len());
        println!("  Total Lines: {}", ext_lines);
        println!("  Total Characters: {}", ext_chars);
        for (rel_path, lines, chars) in file_list {
            println!("    {}: {} lines, {} chars", rel_path, lines, chars);
        }
    }

    println!();
    println!("Total: {} files, {} lines, {} characters", total_files, total_lines, total_chars);
}

fn walk_dir(root: &Path, current: &Path, files: &mut Vec<(String, u64, u64)>) {
    let entries = match fs::read_dir(current) {
        Ok(e) => e,
        Err(_) => return,
    };

    for entry in entries {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue,
        };

        let path = entry.path();

        if path.is_symlink() {
            continue;
        }

        if path.is_dir() {
            walk_dir(root, &path, files);
        } else if path.is_file() {
            let rel = path.strip_prefix(root)
                .unwrap_or(&path)
                .to_string_lossy()
                .to_string();

            let content = match fs::read(&path) {
                Ok(c) => c,
                Err(_) => {
                    files.push((rel, 0, 0));
                    continue;
                }
            };

            let chars = content.len() as u64;
            let lines = if content.is_empty() {
                0
            } else {
                let newline_count = content.iter().filter(|&&b| b == b'\n').count() as u64;
                if content.last() == Some(&b'\n') {
                    newline_count
                } else {
                    newline_count + 1
                }
            };

            files.push((rel, lines, chars));
        }
    }
}

