static void strip_trailing_ws(char *s)
{
    size_t len = strlen(s);
    while (len > 0 && (s[len - 1] == '\n' || s[len - 1] == '\r' ||
                        s[len - 1] == ' '  || s[len - 1] == '\t')) {
        s[len - 1] = '\0';
        len--;
    }
}

static char *run_command(const char *cmd)
{
    FILE *f = popen(cmd, "r");
    if (!f) return NULL;

    size_t cap = 4096;
    char *buf = malloc(cap);
    if (!buf) { pclose(f); return NULL; }
    buf[0] = '\0';

    size_t total = 0;
    size_t n;
    while ((n = fread(buf + total, 1, cap - total - 1, f)) > 0) {
        total += n;
        buf[total] = '\0';
        if (total + 1 >= cap) {
            cap *= 2;
            char *tmp = realloc(buf, cap);
            if (!tmp) { free(buf); pclose(f); return NULL; }
            buf = tmp;
        }
    }

    pclose(f);
    strip_trailing_ws(buf);
    return buf;
}

