import java.io.IOException;
import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;
import java.util.*;

public class Main {
    static class FileInfo {
        String relPath;
        int lines;
        long chars;
        FileInfo(String relPath, int lines, long chars) {
            this.relPath = relPath;
            this.lines = lines;
            this.chars = chars;
        }
    }

    static int countLines(Path file) {
        try {
            byte[] bytes = Files.readAllBytes(file);
            if (bytes.length == 0) return 0;
            int count = 0;
            for (byte b : bytes) {
                if (b == '\n') count++;
            }
            if (bytes[bytes.length - 1] != '\n') count++;
            return count;
        } catch (IOException e) {
            return 0;
        }
    }

    public static void main(String[] args) throws Exception {
        Path root = Paths.get("<tmp>");

        Map<String, List<FileInfo>> extMap = new TreeMap<>();

        Files.walkFileTree(root, new SimpleFileVisitor<Path>() {
            @Override
            public FileVisitResult preVisitDirectory(Path dir, BasicFileAttributes attrs) {
                if (Files.isSymbolicLink(dir)) {
                    return FileVisitResult.SKIP_SUBTREE;
                }
                return FileVisitResult.CONTINUE;
            }

            @Override
            public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) {
                if (Files.isSymbolicLink(file)) {
                    return FileVisitResult.CONTINUE;
                }
                if (!Files.isRegularFile(file)) {
                    return FileVisitResult.CONTINUE;
                }
                String relPath = root.relativize(file).toString().replace('\\', '/');
                long chars = Files.size(file);
                int lines = countLines(file);
                String name = file.getFileName().toString();
                String ext = "";
                int dotIdx = name.lastIndexOf('.');
                if (dotIdx > 0) {
                    ext = name.substring(dotIdx);
                }
                extMap.computeIfAbsent(ext, k -> new ArrayList<>()).add(new FileInfo(relPath, lines, chars));
                return FileVisitResult.CONTINUE;
            }

            @Override
            public FileVisitResult visitFileFailed(Path file, IOException exc) {
                return FileVisitResult.CONTINUE;
            }
        });

        for (List<FileInfo> list : extMap.values()) {
            list.sort(Comparator.comparing(f -> f.relPath));
        }

        StringBuilder sb = new StringBuilder();
        sb.append("=== File Tree Analysis ===\n");
        sb.append("\n");

        int totalFiles = 0;
        long totalLines = 0;
        long totalChars = 0;

        for (Map.Entry<String, List<FileInfo>> entry : extMap.entrySet()) {
            String ext = entry.getKey();
            List<FileInfo> files = entry.getValue();

            long extLines = 0;
            long extChars = 0;
            for (FileInfo f : files) {
                extLines += f.lines;
                extChars += f.chars;
            }

            sb.append("Extension: ").append(ext).append("\n");
            sb.append("  Files: ").append(files.size()).append("\n");
            sb.append("  Total Lines: ").append(extLines).append("\n");
            sb.append("  Total Characters: ").append(extChars).append("\n");

            for (FileInfo f : files) {
                sb.append("    ").append(f.relPath).append(": ").append(f.lines).append(" lines, ").append(f.chars).append(" chars\n");
            }

            totalFiles += files.size();
            totalLines += extLines;
            totalChars += extChars;
        }

        sb.append("\n");
        sb.append("Total: ").append(totalFiles).append(" files, ").append(totalLines).append(" lines, ").append(totalChars).append(" characters\n");

        System.out.print(sb.toString());
    }
}

