typedef struct {
    char **items;
    size_t n, cap;
} StrList;

static void sl_push(StrList *l, const char *s) {
    if (l->n == l->cap) {
        l->cap = l->cap ? l->cap * 2 : 64;
        l->items = (char **)realloc(l->items, l->cap * sizeof(char *));
        if (!l->items) exit(1);
    }
    char *d = (char *)malloc(strlen(s) + 1);
    if (!d) exit(1);
    strcpy(d, s);
    l->items[l->n++] = d;
}

static int sl_contains(StrList *l, const char *s) {
    for (size_t i = 0; i < l->n; i++)
        if (strcmp(l->items[i], s) == 0) return 1;
    return 0;
}

static int cmpstr(const void *a, const void *b) {
    return strcmp(*(char *const *)a, *(char *const *)b);
}

typedef struct {
    StrList keys;
    long *counts;
    size_t ccap;
} Map;

static void map_inc(Map *m, const char *key) {
    for (size_t i = 0; i < m->keys.n; i++)
        if (strcmp(m->keys.items[i], key) == 0) {
            m->counts[i]++;
            return;
        }
    sl_push(&m->keys, key);
    if (m->ccap < m->keys.n) {
        m->ccap = m->keys.cap;
        m->counts = (long *)realloc(m->counts, m->ccap * sizeof(long));
        if (!m->counts) exit(1);
    }
