use std::collections::HashMap;
use std::fs;

enum Json {
    Object(Vec<(String, Json)>),
    Array(Vec<Json>),
    String(String),
    Number(f64),
    Bool(bool),
    Null,
}

struct Parser {
    s: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(s: &str) -> Self {
        Parser { s: s.chars().collect(), pos: 0 }
    }

    fn skip_whitespace(&mut self) {
        while self.pos < self.s.len() && self.s[self.pos].is_whitespace() {
            self.pos += 1;
        }
    }

    fn peek(&self) -> Option<char> {
        self.s.get(self.pos).copied()
    }

    fn next(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn expect(&mut self, c: char) {
        self.skip_whitespace();
        let got = self.next();
        assert_eq!(got, Some(c), "Expected '{}' at pos {}", c, self.pos);
    }

    fn parse_value(&mut self) -> Json {
        self.skip_whitespace();
        match self.peek() {
            Some('{') => self.parse_object(),
            Some('[') => self.parse_array(),
            Some('"') => Json::String(self.parse_string()),
            Some('t') => {
                self.pos += 4;
                Json::Bool(true)
            }
            Some('f') => {
                self.pos += 5;
                Json::Bool(false)
            }
            Some('n') => {
                self.pos += 4;
                Json::Null
            }
            _ => self.parse_number(),
        }
    }

    fn parse_object(&mut self) -> Json {
        self.expect('{');
        let mut pairs = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some('}') {
            self.next();
            return Json::Object(pairs);
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string();
            self.expect(':');
            let val = self.parse_value();
            pairs.push((key, val));
            self.skip_whitespace();
            match self.next() {
                Some(',') => continue,
                Some('}') => break,
                _ => panic!("Expected ',' or '}' in object"),
            }
        }
        Json::Object(pairs)
    }

    fn parse_array(&mut self) -> Json {
        self.expect('[');
        let mut items = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(']') {
            self.next();
            return Json::Array(items);
        }
        loop {
            let val = self.parse_value();
            items.push(val);
            self.skip_whitespace();
            match self.next() {
                Some(',') => continue,
                Some(']') => break,
                _ => panic!("Expected ',' or ']' in array"),
            }
        }
        Json::Array(items)
    }

    fn parse_string(&mut self) -> String {
        self.expect('"');
        let mut result = String::new();
        loop {
            match self.next() {
                Some('"') => break,
                Some('\\') => {
                    match self.next() {
                        Some('"') => result.push('"'),
                        Some('\\') => result.push('\\'),
                        Some('/') => result.push('/'),
                        Some('n') => result.push('\n'),
                        Some('t') => result.push('\t'),
                        Some('r') => result.push('\r'),
                        Some('b') => result.push('\x08'),
                        Some('f') => result.push('\x0c'),
                        Some('u') => {
                            let mut code: u32 = 0;
                            for _ in 0..4 {
                                let c = self.next().unwrap();
                                let digit = match c {
                                    '0'..='9' => c as u32 - '0' as u32,
                                    'a'..='f' => c as u32 - 'a' as u32 + 10,
                                    'A'..='F' => c as u32 - 'A' as u32 + 10,
                                    _ => panic!("Invalid hex digit in \\u escape"),
                                };
                                code = code * 16 + digit;
                            }
                            result.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                        }
                        _ => panic!("Invalid escape sequence"),
                    }
                }
                Some(c) => result.push(c),
                None => panic!("Unterminated string"),
            }
        }
        result
    }

    fn parse_number(&mut self) -> Json {
        self.skip_whitespace();
        let start = self.pos;
        while self.pos < self.s.len() {
            let c = self.s[self.pos];
            if c.is_ascii_digit() || c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E' {
                self.pos += 1;
            } else {
                break;
            }
        }
        let num_str: String = self.s[start..self.pos].iter().collect();
        Json::Number(num_str.parse::<f64>().unwrap())
    }
}

fn fmt_dist(d: f64) -> String {
    if d.fract() == 0.0 {
        format!("{}", d as i64)
    } else {
        format!("{}", d)
    }
}

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read graph.json");

    let mut parser = Parser::new(&content);
    let json = parser.parse_value();

    let (nodes, edges) = match json {
        Json::Object(pairs) => {
            let mut nodes = Vec::new();
            let mut edges = Vec::new();
            for (key, val) in pairs {
                if key == "nodes" {
                    if let Json::Array(arr) = val {
                        for item in arr {
                            if let Json::String(s) = item {
                                nodes.push(s);
                            }
                        }
                    }
                } else if key == "edges" {
                    if let Json::Array(arr) = val {
                        for item in arr {
                            if let Json::Object(epairs) = item {
                                let mut from = String::new();
                                let mut to = String::new();
                                let mut weight = 0.0f64;
                                for (k, v) in epairs {
                                    match k.as_str() {
                                        "from" => {
                                            if let Json::String(s) = v {
                                                from = s;
                                            }
                                        }
                                        "to" => {
                                            if let Json::String(s) = v {
                                                to = s;
                                            }
                                        }
                                        "weight" => {
                                            if let Json::Number(n) = v {
                                                weight = n;
                                            }
                                        }
                                        _ => {}
                                    }
                                }
                                edges.push((from, to, weight));
                            }
                        }
                    }
                }
            }
            (nodes, edges)
        }
        _ => panic!("Expected JSON object at top level"),
    };

    // Build adjacency list (undirected)
    let mut adj: HashMap<String, Vec<(String, f64)>> = HashMap::new();
    for node in &nodes {
        adj.entry(node.clone()).insert(Vec::new());
    }
    for (from, to, weight) in &edges {
        adj.entry(from.clone())
            .or_insert_with(Vec::new)
            .push((to.clone(), *weight));
        adj.entry(to.clone())
            .or_insert_with(Vec::new)
            .push((from.clone(), *weight));
    }

    // Dijkstra's algorithm from "A"
    let start = "A".to_string();
    let mut dist: HashMap<String, f64> = HashMap::new();
    let mut visited: HashMap<String, bool> = HashMap::new();

    for node in &nodes {
        dist.insert(node.clone(), f64::INFINITY);
        visited.insert(node.clone(), false);
    }
    dist.insert(start.clone(), 0.0);

    for _ in 0..nodes.len() {
        let mut min_node: Option<&String> = None;
        let mut min_dist = f64::INFINITY;
        for node in &nodes {
            if !visited[node] && dist[node] < min_dist {
                min_dist = dist[node];
                min_node = Some(node);
            }
        }

        let min_node = match min_node {
            Some(n) => n.clone(),
            None => break,
        };

        visited.insert(min_node.clone(), true);

        if let Some(neighbors) = adj.get(&min_node) {
            for (neighbor, weight) in neighbors {
                let new_dist = dist[&min_node] + weight;
                if new_dist < dist[neighbor] {
                    dist.insert(neighbor.clone(), new_dist);
                }
            }
        }
    }

    // Output
    println!("=== Shortest Paths from A ===");
    println!();

    let mut sorted_nodes: Vec<&String> = nodes.iter().collect();
    sorted_nodes.sort();

    for node in sorted_nodes {
        let d = dist[node];
        if d == f64::INFINITY {
            println!("A -> {}: unreachable", node);
        } else {
            println!("A -> {}: {}", node, fmt_dist(d));
        }
    }
}

