                skip_whitespace(s, pos);
                if *pos < s.len() && s.as_bytes()[*pos] == b',' {
                    *pos += 1;
                } else {
                    break;
                }
            }
            skip_whitespace(s, pos);
            if *pos < s.len() && s.as_bytes()[*pos] == b']' {
                *pos += 1;
            }
            Json::Array(arr)
        }
        b'{' => {
            *pos += 1;
            let mut obj = Vec::new();
            skip_whitespace(s, pos);
            if *pos < s.len() && s.as_bytes()[*pos] == b'}' {
                *pos += 1;
                return Json::Object(obj);
            }
            loop {
                skip_whitespace(s, pos);
                if *pos >= s.len() { break; }
                if s.as_bytes()[*pos] == b'}' {
                    *pos += 1;
                    break;
                }
                let key = parse_string(s, pos);
                skip_whitespace(s, pos);
                if *pos < s.len() && s.as_bytes()[*pos] == b':' {
                    *pos += 1;
                }
                let val = parse_value(s, pos);
                obj.push((key, val));
                skip_whitespace(s, pos);
                if *pos < s.len() && s.as_bytes()[*pos] == b',' {
                    *pos += 1;
                } else {
                    break;
                }
            }
            skip_whitespace(s, pos);
            if *pos < s.len() && s.as_bytes()[*pos] == b'}' {
                *pos += 1;
            }
            Json::Object(obj)
        }
        b'"' => Json::String(parse_string(s, pos)),
        b't' => { *pos += 4; Json::Bool(true) }
        b'f' => { *pos += 5; Json::Bool(false) }
        b'n' => { *pos += 4; Json::Null }
        _ => Json::Number(parse_number(s, pos)),
    }
}

fn get_obj_field<'a>(obj: &'a Json, key: &str) -> Option<&'a Json> {
    if let Json::Object(pairs) = obj {
        for (k, v) in pairs {
            if k == key {
                return Some(v);
            }
        }
    }
    None
}

fn main() {
    let mut stream = TcpStream::connect("127.0.0.1:18923").expect("Failed to connect");
    let request = "GET /api/products HTTP/1.1\r\nHost: 127.0.0.1:18923\r\nConnection: close\r\n\r\n";
    stream.write_all(request.as_bytes()).expect("Failed to write request");

    let mut response = Vec::new();
    let mut buf = [0u8; 4096];
    loop {
        let n = stream.read(&mut buf).unwrap_or(0);
        if n == 0 {
            break;
        }
        response.extend_from_slice(&buf[..n]);
    }

    let response_str = String::from_utf8(response).expect("Invalid UTF-8 in response");
    let body_start = response_str.find("\r\n\r\n").map(|i| i + 4).unwrap_or(0);
    let body = &response_str[body_start..];

    let mut pos = 0;
    let json = parse_value(body, &mut pos);

    let mut filtered: Vec<(String, f64)> = Vec::new();
    if let Json::Array(arr) = &json {
        for item in arr {
            if let Json::Object(_) = item {
                let name = get_obj_field(item, "name")
                    .and_then(|v| if let Json::String(s) = v { Some(s.clone()) } else { None })
                    .unwrap_or_default();
                let price = get_obj_field(item, "price")
                    .and_then(|v| if let Json::Number(n) = v { Some(*n) } else { None })
                    .unwrap_or(0.0);
                if price > 50.00 {
                    filtered.push((name, price));
                }
            }
        }
    }

    filtered.sort_by(|a, b| a.0.cmp(&b.0));

    println!("=== Filtered Products (price > $50.00) ===");
    println!();
    for (name, price) in &filtered {
        println!("{}: ${:.2}", name, price);
    }
    println!();
    println!("Count: {}", filtered.len());
    let total: f64 = filtered.iter().map(|(_, p)| p).sum();
    println!("Total: ${:.2}", total);
}
