static const char *json;
static size_t json_len;
static size_t pos;

static void skip_ws(void) {
    while (pos < json_len && (json[pos]==' '||json[pos]=='\t'||json[pos]=='\n'||json[pos]=='\r'))
        pos++;
}

static char *parse_string(void) {
    skip_ws();
    if (pos >= json_len || json[pos] != '"') return NULL;
    pos++;
    size_t cap = 64, len = 0;
    char *s = malloc(cap);
    while (pos < json_len && json[pos] != '"') {
        if (len >= cap - 1) {
            cap *= 2;
            s = realloc(s, cap);
        }
        if (json[pos] == '\\') {
            pos++;
            if (pos < json_len) s[len++] = json[pos++];
        } else {
            s[len++] = json[pos++];
        }
    }
    if (pos < json_len) pos++;
    s[len] = '\0';
    return s;
}

static double parse_number(void) {
    skip_ws();
    char buf[64];
