    double *dist = malloc((size_t)num_nodes * sizeof(double));
    int *visited = calloc((size_t)num_nodes, sizeof(int));
    for (int i = 0; i < num_nodes; i++) dist[i] = 1e18;
    dist[src_idx] = 0.0;

    for (int iter = 0; iter < num_nodes; iter++) {
        int u = -1;
        double min_d = 1e18;
        for (int i = 0; i < num_nodes; i++) {
            if (!visited[i] && dist[i] < min_d) {
                min_d = dist[i];
                u = i;
            }
        }
        if (u == -1) break;
        visited[u] = 1;

        for (int j = 0; j < adj_deg[u]; j++) {
            int v = adj[u][j];
            double w = edge_w[adj_eidx[u][j]];
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
            }
        }
    }

    /* Sort node indices alphabetically */
    int *order = malloc((size_t)num_nodes * sizeof(int));
    for (int i = 0; i < num_nodes; i++) order[i] = i;
    for (int i = 0; i < num_nodes; i++) {
        for (int j = i + 1; j < num_nodes; j++) {
            if (strcmp(nodes[order[i]], nodes[order[j]]) > 0) {
                int tmp = order[i];
                order[i] = order[j];
                order[j] = tmp;
            }
        }
    }

    /* Output */
    printf("=== Shortest Paths from A ===\n\n");
    for (int i = 0; i < num_nodes; i++) {
        int idx = order[i];
        double d = dist[idx];
        if (d >= 1e17) {
            printf("A -> %s: unreachable\n", nodes[idx]);
        } else if (fabs(d - (double)(long long)d) < 1e-9) {
            printf("A -> %s: %lld\n", nodes[idx], (long long)d);
        } else {
            printf("A -> %s: %.1f\n", nodes[idx], d);
        }
    }

    free(json);
    return 0;
