import Foundation

let baseDir = "<tmp>"
let baseURL = URL(fileURLWithPath: baseDir)
let fm = FileManager.default

struct FileEntry {
    let relativePath: String
    let lines: Int
    let chars: Int
}

var allFiles: [String: [FileEntry]] = [:]

func getExtension(_ url: URL) -> String {
    let ext = url.pathExtension
    if ext.isEmpty {
        return "(none)"
    }
    return "." + ext
}

func analyzeFile(_ url: URL) -> (lines: Int, chars: Int) {
    guard let data = try? Data(contentsOf: url) else { return (0, 0) }
    let chars = data.count
    if data.isEmpty { return (0, 0) }
    var lines = 0
    for byte in data {
        if byte == 0x0A {
            lines += 1
        }
    }
    if data[data.count - 1] != 0x0A {
        lines += 1
    }
    return (lines, chars)
}

func walk(_ url: URL, visited: inout Set<String>) {
    let path = url.path
    if visited.contains(path) { return }
    visited.insert(path)

    guard let contents = try? fm.contentsOfDirectory(
        at: url,
        includingPropertiesForKeys: [.isSymbolicLinkKey, .isDirectoryKey],
        options: []
    ) else { return }

    for item in contents {
        let isSymlink = (try? item.resourceValues(forKeys: [.isSymbolicLinkKey]))?.isSymbolicLink ?? false
        if isSymlink { continue }

        let isDir = (try? item.resourceValues(forKeys: [.isDirectoryKey]))?.isDirectory ?? false

        if isDir {
            walk(item, visited: &visited)
        } else {
            let relPath = String(item.path.dropFirst(baseDir.count + 1))
            let ext = getExtension(item)
            let (lines, chars) = analyzeFile(item)
            let entry = FileEntry(relativePath: relPath, lines: lines, chars: chars)
            allFiles[ext, default: []].append(entry)
        }
    }
}

var visited = Set<String>()
walk(baseURL, visited: &visited)

print("=== File Tree Analysis ===")
print("")

var totalFiles = 0
var totalLines = 0
var totalChars = 0

let sortedExts = allFiles.keys.sorted()

for ext in sortedExts {
    var files = allFiles[ext]!
    files.sort { $0.relativePath < $1.relativePath }

    let fileCount = files.count
    let extLines = files.reduce(0) { $0 + $1.lines }
    let extChars = files.reduce(0) { $0 + $1.chars }

    print("Extension: \(ext)")
    print("  Files: \(fileCount)")
    print("  Total Lines: \(extLines)")
    print("  Total Characters: \(extChars)")

    for f in files {
        print("    \(f.relativePath): \(f.lines) lines, \(f.chars) chars")
    }

    totalFiles += fileCount
    totalLines += extLines
    totalChars += extChars
}

print("")
print("Total: \(totalFiles) files, \(totalLines) lines, \(totalChars) characters")

