func getExtension(_ url: URL) -> String {
    let ext = url.pathExtension
    if ext.isEmpty {
        return "(none)"
    }
    return "." + ext
}

func analyzeFile(_ url: URL) -> (lines: Int, chars: Int) {
    guard let data = try? Data(contentsOf: url) else { return (0, 0) }
    let chars = data.count
    if data.isEmpty { return (0, 0) }
    var lines = 0
    for byte in data {
        if byte == 0x0A {
            lines += 1
        }
    }
    if data[data.count - 1] != 0x0A {
        lines += 1
    }
    return (lines, chars)
}

let basePath = baseURL.path

func walk(_ url: URL, visited: inout Set<String>) {
    let path = url.path
    if visited.contains(path) { return }
