static void add_entry(const char *relpath, const char *ext, long long lines, long long chars) {
    if (num_entries >= entry_cap) {
        entry_cap = entry_cap ? entry_cap * 2 : 128;
        entries = xrealloc(entries, (size_t)entry_cap * sizeof(FileEntry));
    }
    entries[num_entries].relpath = xstrdup(relpath);
    entries[num_entries].ext = xstrdup(ext);
    entries[num_entries].lines = lines;
    entries[num_entries].chars = chars;
