    FILE *f = fopen(path, "rb");
    if (!f) {
        *out_lines = 0;
        return 0;
    }

    long long chars = 0;
    long long lines = 0;
    int last_was_newline = 0;
    int had_content = 0;
    enum { BUFSZ = 65536 };
    char *buf = malloc(BUFSZ);
    if (!buf) { fclose(f); *out_lines = 0; return 0; }

