    while ((n = fread(buf, 1, BUFSZ, f)) > 0) {
        for (size_t i = 0; i < n; i++) {
            chars++;
            if (buf[i] == '\n') {
                lines++;
                last_was_newline = 1;
            } else {
                last_was_newline = 0;
            }
        }
        had_content = 1;
    }

    free(buf);

    if (had_content && !last_was_newline) {
        lines++;
    }

    fclose(f);
    *out_lines = lines;
    return chars;
}

