                   entries[k].relpath, entries[k].lines, entries[k].chars);
        }

        i = j;
    }

    long long total_files = (long long)num_entries;
    long long total_lines = 0;
    long long total_chars = 0;
    for (int k = 0; k < num_entries; k++) {
        total_lines += entries[k].lines;
        total_chars += entries[k].chars;
    }

    printf("\n");
    printf("Total: %lld files, %lld lines, %lld characters\n",
           total_files, total_lines, total_chars);

    for (int k = 0; k < num_entries; k++) {
        free(entries[k].relpath);
        free(entries[k].ext);
    }
    free(entries);

    return 0;
}
